"use strict";
const memoryTracks=[
 {id:'nostalgia-original',name:'口袋里的夏天',credit:'本站原创 · 8位合成旋律',seconds:30},
 {id:'moon-letter',name:'月光来信',credit:'本站原创 · 慢板合成旋律',seconds:32},
 {id:'summer-ringtone',name:'夏日来电',credit:'本站原创 · 铃声风格旋律',seconds:30},
 {id:'elise-memory',name:'致爱丽丝 · 记忆铃声',credit:'贝多芬公版旋律 · 本站合成演奏',seconds:34}
];
let memoryTrack=0;
function setMemoryTrack(index,play=true){memoryTrack=((index%memoryTracks.length)+memoryTracks.length)%memoryTracks.length;const a=$('#retro-audio');a.src=`audio/${memoryTracks[memoryTrack].id}.mp3`;a.volume=.35;if(play)a.play().catch(()=>toast('请再点一次播放按钮'));if(current.type==='music')navigate(current,false);if(current.type==='phone')refreshPhone();}
function salonNav(){return `<nav class="salon-nav"><button data-action="home">‹ 时光首页</button><button data-world-channel="music">音乐</button><button data-world-channel="videos">视频</button><button data-phone-lab>装进口袋</button><button data-capture-view>保存这一页</button></nav>`;}
function renderMusicSalon(){const t=memoryTracks[memoryTrack];return `<section class="music-salon">${salonNav()}<header><small>PERSONAL STEREO / 随身听俱乐部</small><h1>把耳机分你一半。</h1><p>一首歌循环很久，一个夏天也很长。</p></header><div class="stereo-shell"><div class="stereo-label">OLD DAYS <span>DIGITAL AUDIO PLAYER</span></div><div class="stereo-lcd"><small>TRACK 0${memoryTrack+1} / MEMORY MIX</small><h2>${escapeHTML(t.name)}</h2><div class="stereo-bars">▂ ▅ ▃ ▇ ▄ ▆ ▂ ▅ ▃ ▇ ▂ ▄</div><p>${t.seconds} SEC · LOOP · STEREO</p></div><div class="stereo-buttons"><button data-track-step="-1" aria-label="上一首">|◀</button><button data-music-toggle>${$('#retro-audio').paused?'▶ 播放':'Ⅱ 暂停'}</button><button data-track-step="1" aria-label="下一首">▶|</button><label>音量 <input data-music-volume type="range" min="0" max="100" value="${Math.round(($('#retro-audio').volume||.35)*100)}" aria-label="随身听音量"></label></div><p>${escapeHTML(t.credit)} · 手动播放</p></div><div class="memory-playlist">${memoryTracks.map((x,i)=>`<button data-memory-track="${i}" class="${i===memoryTrack?'selected':''}"><b>0${i+1}</b><span>${x.name}<small>${x.credit}</small></span><time>0:${x.seconds}</time></button>`).join('')}</div><div class="salon-sidenote">这些是为怀旧体验制作的配乐与合成演奏，不是当年的流行歌曲录音。想找旧音乐网页？${[['百度MP3','mp3.baidu.com'],['九天音乐','www.9sky.com'],['一听音乐','www.1ting.com'],['千千静听','www.ttplayer.com']].map(([n,u])=>siteLink(n,u)).join('')}</div>${eraAdvertMarkup('strip',1)}</section>`;}
function renderVideoSalon(){const films=eraFilms.filter(f=>f.year<=Number(year()));return `<section class="video-salon">${salonNav()}<header><small>PICTURE HOUSE / 宽频放映室</small><h1>缓冲好了，开始放映。</h1><p>${year()} 年 · 只展示这一年以前已发布的影片。</p></header>${films.length?films.map(f=>`<article class="salon-film"><div class="film-frame"><span>▶ ${f.year} / OPEN MOVIE</span><video controls playsinline preload="none" src="${f.src}" aria-label="${escapeHTML(f.title)}"></video></div><h2>${escapeHTML(f.title)}</h2><p>${escapeHTML(f.credit)} · <a href="${f.source}" target="_blank" rel="noopener noreferrer">原始来源</a> · <a href="${f.license}" target="_blank" rel="noopener noreferrer">${escapeHTML(f.licenseLabel||"CC BY 许可")}</a></p><small>年代开放影像资料，不代表当年热门排行。由原始资料站提供流媒体，播放需要网络。</small></article>`).join(''):`<div class="film-empty"><b>▣ ${year()} · 影像档案柜</b><p>这个年份尚未收录可直接播放的授权影片。可以先探索当年的视频旧站，或切换到 2001 年以后观看开放影像。</p></div>`}<div class="video-old-links">${[['央视国际','www.cctv.com',1996],['闪客帝国','www.flashempire.com',1999],['土豆网','www.tudou.com',2005],['优酷','www.youku.com',2006],['56网','www.56.com',2005],['AcFun','www.acfun.cn',2007]].filter(x=>x[2]<=Number(year())).map(([n,u])=>siteLink(n,u)).join('')}</div>${eraAdvertMarkup('strip',2)}</section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-memory-track],[data-track-step],[data-phone-track]');if(!b)return;e.preventDefault();if(b.dataset.memoryTrack!==undefined)setMemoryTrack(Number(b.dataset.memoryTrack));else setMemoryTrack(memoryTrack+(b.dataset.phoneTrack?b.dataset.phoneTrack==='prev'?-1:1:Number(b.dataset.trackStep||1)));});
